```kotlin
package com.kdi.application

import android.annotation.SuppressLint
import android.util.Size
import androidx.annotation.OptIn
import androidx.camera.core.CameraSelector
import androidx.camera.core.ExperimentalGetImage
import androidx.camera.core.ImageAnalysis
import androidx.camera.core.ImageProxy
import androidx.camera.lifecycle.ProcessCameraProvider
import androidx.camera.view.PreviewView
import androidx.core.content.ContextCompat
import androidx.lifecycle.LifecycleOwner
import com.google.mlkit.vision.barcode.BarcodeScanner
import com.google.mlkit.vision.barcode.BarcodeScanning
import com.google.mlkit.vision.common.InputImage
import java.util.concurrent.ExecutorService
import java.util.concurrent.Executors

class QRCodeScanner(
    private val lifecycleOwner: LifecycleOwner,
    private val previewView: PreviewView,
    private val onQRCodeScanned: (String) -> Unit
) : IQRCodeScanner {

    private val cameraExecutor: ExecutorService = Executors.newSingleThreadExecutor()
    private val barcodeScanner: BarcodeScanner = BarcodeScanning.getClient()
    private var isScanningActive = true // Flag to control scanning

    override fun startCamera() {
        val cameraProviderFuture = ProcessCameraProvider.getInstance(previewView.context)
        cameraProviderFuture.addListener({
            val cameraProvider = cameraProviderFuture.get()
            bindPreviewAndAnalysis(cameraProvider)
        }, ContextCompat.getMainExecutor(previewView.context))
    }

    @SuppressLint("UnsafeOptInUsageError")
    private fun bindPreviewAndAnalysis(cameraProvider: ProcessCameraProvider) {
        val preview = androidx.camera.core.Preview.Builder()
            .build().also {
                it.setSurfaceProvider(previewView.surfaceProvider)
            }

        val cameraSelector = CameraSelector.DEFAULT_BACK_CAMERA

        val imageAnalysis = ImageAnalysis.Builder()
            .setTargetResolution(Size(1280, 720))
            .setBackpressureStrategy(ImageAnalysis.STRATEGY_KEEP_ONLY_LATEST)
            .build()

        imageAnalysis.setAnalyzer(cameraExecutor) { imageProxy ->
            processImage(imageProxy)
        }

        cameraProvider.unbindAll()
        cameraProvider.bindToLifecycle(
            lifecycleOwner,
            cameraSelector,
            preview,
            imageAnalysis
        )
    }

    @OptIn(ExperimentalGetImage::class)
    private fun processImage(imageProxy: ImageProxy) {
        if (!isScanningActive) {
            imageProxy.close() // Close the image proxy immediately
            return
        }

        val mediaImage = imageProxy.image
        if (mediaImage != null) {
            val inputImage = InputImage.fromMediaImage(mediaImage, imageProxy.imageInfo.rotationDegrees)
            barcodeScanner.process(inputImage)
                .addOnSuccessListener { barcodes ->
                    if (barcodes.isNotEmpty()) {
                        // Stop scanning once a QR code is found
                        isScanningActive = false
                        for (barcode in barcodes) {
                            barcode.rawValue?.let { onQRCodeScanned(it) }
                        }
                        stopCamera() // Stop the camera
                    }
                }
                .addOnFailureListener { e ->
                    Log.e("QRCodeScanner", "Error processing image: ${e.message}")
                }
                .addOnCompleteListener { imageProxy.close() }
        } else {
            imageProxy.close()
        }
    }

    override fun stopCamera() {
        isScanningActive = false // Prevent further scanning
        cameraExecutor.shutdown()
    }
}
```

