                android.R.anim.fade_in, // Pop enter animation (backstack)
                android.R.anim.fade_out // Pop exit animation (backstack)
            )
            .replace(R.id.main, targetFragment) // Replace the current fragment
            .addToBackStack(null) // Optional: Add to backstack
            .commit()
    }

    /**
     * Fades in the TextView over a specified duration.
     * @param duration Duration for the fade-in effect.
     */
    suspend fun TextView.fadeIn(duration: Long = 300L) =
        suspendCancellableCoroutine<Unit> { continuation ->
            this.apply {
                visibility = View.VISIBLE
                alpha = 0f
                animate()
                    .alpha(1f)
                    .setDuration(duration)
                    .withEndAction {
                        if (continuation.isActive) {
                            continuation.resume(Unit) {}
                        }
                    }
            }
        }

    /**
     * Fades out the TextView over a specified duration.
     * @param duration Duration for the fade-out effect.
     */
    suspend fun TextView.fadeOut(duration: Long = 300L) =
        suspendCancellableCoroutine<Unit> { continuation ->
            this.animate()
                .alpha(0f)
                .setDuration(duration)
                .withEndAction {
                    visibility = View.GONE // Make it invisible
                    if (continuation.isActive) {
                        continuation.resume(Unit) {}
                    }
                }
        }
}
